import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validates authentication requirement for administrator password change API.
 *
 * This test checks if unauthenticated (no JWT token) access to the administrator password change endpoint is properly blocked. It attempts to invoke the password change API without providing any authentication, and expects an error indicating that authentication or authorization is required. This ensures that the endpoint is secured and cannot be accessed by unauthenticated users.
 *
 * 1. Attempt to change the password as an administrator without setting any authentication headers (no JWT token included in connection object).
 * 2. Expect the API to return an authentication or authorization error (error is thrown).
 */
export async function test_api_administrator_change_password_requires_authentication(
  connection: api.IConnection,
) {
  await TestValidator.error("should throw if unauthenticated")(
    async () => {
      await api.functional.auth.administrator.password.changePassword(connection, {
        body: {
          current_password: "irrelevantOldPassword",
          new_password: "irrelevantNewPassword123",
        } satisfies IAdministrator.IChangePassword,
      });
    },
  );
}

