import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuthLoginRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthLoginRequest";
import type { ISellerAuthTokenResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthTokenResponse";

/**
 * Test seller login with an unregistered email address.
 *
 * This test verifies that the seller authentication endpoint properly handles login attempts using an email address that has never been registered. The API should fail the login, returning an error indicating invalid credentials or non-existent seller. No tokens (access or refresh) should be issued in this scenario.
 *
 * Steps:
 * 1. Create random, unique seller email and password (ensuring the account does not exist).
 * 2. Attempt to log in as a seller using the email and password via /auth/seller/login.
 * 3. Verify that an error is returned, indicating the credentials are invalid or the seller does not exist.
 * 4. Confirm no token data is returned in the error case.
 */
export async function test_api_seller_login_nonexistent_email(connection: api.IConnection) {
  // 1. Generate credentials for non-existent seller
  const email = typia.random<string & tags.Format<"email">>();
  const password = "randomPassword123!";

  // 2. Attempt login and assert that it fails
  await TestValidator.error("login with nonexistent email should fail")(async () => {
    await api.functional.auth.seller.login.signIn(connection, {
      body: {
        email,
        password,
      } satisfies ISellerAuthLoginRequest,
    });
  });
}

