import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";

/**
 * Validate seller registration with an invalid email format.
 *
 * In this test, we simulate an attempt to register a new seller account using an invalid email address (for example, omitting the '@' character or the domain). The API is expected to enforce email format validation and should reject the registration, returning a validation error and NOT creating the account.
 *
 * This E2E test ensures the system's registration endpoint correctly enforces basic email format requirements, preventing users from onboarding with malformed addresses.
 *
 * Steps:
 * 1. Attempt seller registration with an invalid email format (e.g., "invalid-email-format" without '@' or domain).
 * 2. Confirm that the registration fails and a validation error (type error) is thrown by the API.
 * 3. Ensure that no seller account is created as a result of this request.
 */
export async function test_api_seller_registration_invalid_email_format(
  connection: api.IConnection,
) {
  // 1. Attempt seller registration with invalid email format
  const invalidInput = {
    email: "invalid-email-format", // purposely missing '@' and domain
    password: "ValidPassw0rd!",
    business_registration_number: "123-45-67890",
    display_name: "Invalid Email Seller",
  } satisfies ISellerAuthRegisterRequest;

  // 2. The API should throw a validation/type error
  await TestValidator.error("Should return validation error for invalid email")(
    () => api.functional.auth.seller.register.signUp(connection, { body: invalidInput }),
  );

  // 3. (Optional) Further validation can include querying for the account, but is omitted if no search/read API exists for sellers by email.
}

