import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate that attempting to soft-delete a nonexistent attachment is properly handled.
 *
 * Only administrators are permitted to attempt deletion of attachments. This test covers:
 * - Register a new admin (required for endpoint access)
 * - Login as the registered administrator to obtain auth context
 * - Attempt a soft-delete (DELETE /shoppingMallAi/administrator/attachments/{attachmentId}) using a random UUID that does NOT correspond to any actual record
 * - The API must respond with an error indicating the target does not exist ("not found" or equivalent)
 * - Successful assertion is that system rejects missing records, consistent with compliance and audit requirements
 */
export async function test_api_attachment_soft_delete_nonexistent_attachment(
  connection: api.IConnection,
) {
  // 1. Register a new administrator to gain endpoint privileges
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<string>();
  const admin: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
      display_name: RandomGenerator.name(),
      status: "active",
      role: "superadmin"
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(admin);

  // 2. Login as the admin (get a fresh auth session, ensure JWT header in connection)
  const login: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(login);

  // 3. Attempt deletion with a random, non-existent UUID
  const nonexistentAttachmentId: string = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("nonexistent attachment deletion fails")(async () => {
    await api.functional.shoppingMallAi.administrator.attachments.erase(connection, {
      attachmentId: nonexistentAttachmentId,
    });
  });
}

