import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate that administrator login fails when the admin account status is not 'active'.
 *
 * Business context: Only administrators with status 'active' are allowed to log in and receive JWT tokens. Suspended, withdrawn, and banned admins must not be able to authenticate.
 *
 * This test ensures that for each non-active status value ('suspended','withdrawn','banned'), an administrator registration can be completed and login, then login is attempted with those credentials, and the attempt is properly rejected by the login endpoint. The rejection must prevent issuing any JWT credentials.
 *
 * Step-by-step:
 * 1. For each non-active status ('suspended','withdrawn','banned'):
 *   a. Register a new administrator with that status using the registration API
 *   b. Attempt to log in as that administrator with the same email/password
 *   c. Assert that the login is rejected (an error is thrown)
 *   d. Confirm that no JWT token is issued in the login response (there is no Authorization in setHeaders)
 */
export async function test_api_administrator_login_fails_for_non_active_status(
  connection: api.IConnection,
) {
  // Array of the three non-active administrator status enums
  const nonActiveStatuses = ['suspended','withdrawn','banned'];

  for (const status of nonActiveStatuses) {
    // Step 1a: Register a new administrator with current status
    const email = typia.random<string & tags.Format<"email">>();
    const passwordHash = RandomGenerator.alphaNumeric(32);
    const displayName = RandomGenerator.alphaNumeric(12);
    const role = 'reviewer';

    const newAdmin = await api.functional.auth.administrator.register.signUp(connection, {
      body: {
        email,
        password_hash: passwordHash,
        display_name: displayName,
        status,
        role
      } satisfies IAdministrator.ICreate,
    });
    typia.assert(newAdmin);
    TestValidator.equals('admin status')(newAdmin.status)(status);

    // Step 1b: Attempt to log in (should fail)
    await TestValidator.error(`login fails for status=${status}`)(async () => {
      await api.functional.auth.administrator.login.signIn(connection, {
        body: {
          email,
          password_hash: passwordHash,
        } satisfies IAdministrator.ILogin
      });
    });
  }
}

