import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate the error behavior when attempting to delete a non-existent or already deleted attachment version.
 *
 * This test ensures that: (1) only authenticated administrators can attempt the attachment version deletion, and (2) the system correctly refuses deletion of a versionId that does not exist by returning a not found or already deleted error, without altering any system state or creating side effects.
 *
 * Steps:
 * 1. Register a new administrator account using random but valid credentials.
 * 2. Log in as the new administrator and obtain authorization.
 * 3. Attempt to delete an attachment version using valid UUIDs that do not correspond to any existing or undeleted version (i.e., random non-existent UUIDs).
 * 4. Check that the API call results in an error (HTTP 404 Not Found or equivalent), confirming correct error semantics for invalid/deleted entities. There must be no side effects or resource changes.
 */
export async function test_api_attachment_version_delete_not_found_error(
  connection: api.IConnection,
) {
  // 1. Register a new administrator
  const email = typia.random<string & tags.Format<"email">>();
  const password_hash = RandomGenerator.alphaNumeric(24);
  const display_name = RandomGenerator.name();
  const status = "active"; // Required valid enum from docs
  const role = "superadmin"; // Use generic highest privileges
  const admin = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email,
      password_hash,
      display_name,
      status,
      role,
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(admin);
  // 2. Log in as this administrator (simulate fresh session)
  const login = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email,
      password_hash,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(login);
  // Set Authorization for subsequent admin calls
  connection.headers = {
    ...connection.headers,
    Authorization: login.setHeaders.Authorization,
  };
  // 3. Try to delete a non-existent attachment version
  const nonExistentAttachmentId = typia.random<string & tags.Format<"uuid">>();
  const nonExistentVersionId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("should throw not-found on non-existent attachment version deletion")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.erase(connection, {
        attachmentId: nonExistentAttachmentId,
        attachmentVersionId: nonExistentVersionId,
      });
    },
  );
}

