  const uniqueAdminEmail = typia.random<string & tags.Format<"email">>();
  const passwordHash = "$2b$12$" + RandomGenerator.alphaNumeric(22); // plausible bcrypt format
  const administrator = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
