import type { IAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachment";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate that an administrator can retrieve details of a specific attachment-business link via ID and that all returned fields are correct and complete.
 *
 * Business context:
 * Attachment-business links join uploaded files to various business objects in the AI-powered shopping mall. Administrators must be able to discover full traceability details by link ID, including which object, domain, who linked, and when. Security requires that only an authenticated admin can access this information.
 *
 * Test Steps:
 * 1. Register a new administrator, supplying a unique email, password hash, display name, account status, and role. Capture ID and JWT from the setHeaders.
 * 2. Login as the administrator using the same credentials (verifies login functionality and header issuance).
 * 3. Create a new attachment for the administrator, filling all required fields of IShoppingMallAiAttachment.ICreate. The uploaded_by_id should be the administrator's ID from the registration/login step (business rule: must be set from backend context, but for controlled E2E flow, provide explicitly at this step).
 * 4. Create a new attachment-business link (AttachmentBusinessLink.ICreate) for the attachment, with:
 *    - target_domain: an arbitrary string like 'product' or 'evidence'
 *    - target_id: generate a random uuid
 *    - linked_by_id: administrator's ID
 * 5. Call the GET /shoppingMallAi/administrator/attachments/{attachmentId}/attachmentBusinessLinks/{attachmentBusinessLinkId} using the IDs for attachment and business link.
 * 6. Assert that response matches the schema and contains correct attachment_id, target_domain, target_id, linked_by_id, and a valid ISO creation timestamp. Only authenticated admin can retrieve; access control is therefore verified by virtue of test passing successfully.
 */
export async function test_api_attachment_business_link_get_success(connection: api.IConnection) {
  // 1. Register administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const passwordHash = RandomGenerator.alphaNumeric(32);
  const displayName = RandomGenerator.name();
  const role = "superadmin";
  const admin = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: passwordHash,
      display_name: displayName,
      status: "active",
      role
    }
  });
  typia.assert(admin);

  // 2. Login as administrator
  const loggedInAdmin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: passwordHash
    }
  });
  typia.assert(loggedInAdmin);
  TestValidator.equals("admin ID match after login")(admin.id)(loggedInAdmin.id);
  TestValidator.equals("login setHeaders.Authorization")(loggedInAdmin.setHeaders.Authorization)(admin.setHeaders.Authorization);

  // 3. Create new attachment (uploaded_by_id should be admin.id)
  const attachmentInput = {
    uploaded_by_id: admin.id,
    filename: RandomGenerator.alphaNumeric(12),
    mime_type: "image/jpeg",
    file_uri: `https://cdn.mall/${RandomGenerator.alphaNumeric(24)}`,
    file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<10000>>() ,
    business_domain: "evidence",
    retention_policy_code: "standard",
    legal_hold: false,
    access_acl: "{\"role\":\"admin\"}"
  } satisfies IShoppingMallAiAttachment.ICreate;
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: attachmentInput
  });
  typia.assert(attachment);
  TestValidator.equals("attachment.uploaded_by_id matches")(attachment.uploaded_by_id)(admin.id);

  // 4. Create attachment-business link
  const targetDomain = "product";
  const targetId = typia.random<string & tags.Format<"uuid">>();
  const linkInput = {
    target_domain: targetDomain,
    target_id: targetId,
    linked_by_id: admin.id
  } satisfies IAttachment.AttachmentBusinessLink.ICreate;
  const businessLink = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.create(connection, {
    attachmentId: attachment.id,
    body: linkInput
  });
  typia.assert(businessLink);
  TestValidator.equals("business link attachment_id")(businessLink.attachment_id)(attachment.id);
  TestValidator.equals("business link domain")(businessLink.target_domain)(targetDomain);
  TestValidator.equals("business link target_id")(businessLink.target_id)(targetId);
  TestValidator.equals("business link linked_by_id")(businessLink.linked_by_id)(admin.id);

  // 5. GET operation on the attachment-business link
  const readLink = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.at(connection, {
    attachmentId: attachment.id,
    attachmentBusinessLinkId: businessLink.id
  });
  typia.assert(readLink);
  TestValidator.equals("link.id matches created link")(readLink.id)(businessLink.id);
  TestValidator.equals("link attachment_id")(readLink.attachment_id)(attachment.id);
  TestValidator.equals("link target_domain")(readLink.target_domain)(targetDomain);
  TestValidator.equals("link target_id")(readLink.target_id)(targetId);
  TestValidator.equals("link linked_by_id")(readLink.linked_by_id)(admin.id);
  TestValidator.predicate("created_at is ISO8601 datetime")(typeof readLink.created_at === "string" && !isNaN(Date.parse(readLink.created_at)));
}

