import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCustomer";

/**
 * Validate customer JWT token handling and failure conditions.
 *
 * - Validates authentication session for customer JWT issued via register and login flow.
 * - Checks correct handling of valid, tampered, and expired/invalid tokens.
 * - Simulates backend deactivation state for user.
 *
 * Step-by-step:
 * 1. Generate a new unique email, password, and nickname.
 * 2. Register a new customer using the above credentials.
 * 3. Assert output type and extract the JWT token from setHeaders.Authorization.
 * 4. Immediately call login with same credentials to obtain a fresh JWT as well; validate this token too.
 * 5. For both tokens, call the validate endpoint, assert isValid = true, status = "active", userId matches, and expiration is in the future.
 * 6. Tamper each token (e.g., alter a character), use validate endpoint, and assert error is thrown.
 * 7. Use clearly invalid token (e.g., "garbage.invalid.token"), expect validation error.
 * 8. (System limitation: we cannot deactivate or delete user in test due to lack of API, so skip real status change.)
 * 9. All responses must be type-asserted.
 */
export async function test_api_customer_token_validation_active_and_invalid_token(connection: api.IConnection) {
  // 1. Generate registration info
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPass123!";
  const nickname = RandomGenerator.name();

  // 2. Register new customer and extract JWT
  const registration = await api.functional.auth.customer.register.post.signUp(connection, {
    body: { email, password, nickname } satisfies IShoppingMallAiCustomer.SignUp,
  });
  typia.assert(registration);
  const regJwt = registration.setHeaders.Authorization;
  TestValidator.predicate("JWT token issued by register")(typeof regJwt === "string" && regJwt.length > 10);

  // 3. Login to get a fresh JWT (should be different from registration JWT)
  const login = await api.functional.auth.customer.login.post.signIn(connection, {
    body: { email, password } satisfies IShoppingMallAiCustomer.SignIn,
  });
  typia.assert(login);
  const loginJwt = login.setHeaders.Authorization;
  TestValidator.predicate("JWT token issued by login")(typeof loginJwt === "string" && loginJwt.length > 10);

  // 4. Validate both tokens
  for (const [title, jwt] of [["register", regJwt], ["login", loginJwt]] as const) {
    const result = await api.functional.auth.customer.validate.post.validateToken(connection, {
      body: { jwt } satisfies IShoppingMallAiCustomer.ValidateToken,
    });
    typia.assert(result);
    TestValidator.predicate(`${title} token is valid`)(result.isValid === true);
    TestValidator.equals(`${title} token status active`)(result.status)("active");
    TestValidator.equals(`${title} user id matches`)(result.userId)(registration.id);
    TestValidator.predicate(`${title} exp in future`)(typeof result.exp === "number" && result.exp > Math.floor(Date.now() / 1000));
  }

  // 5. Tampered tokens: alter a character and expect error
  for (const [title, jwt] of [["register", regJwt], ["login", loginJwt]] as const) {
    const tampered = jwt.slice(0, -2) + (jwt.slice(-2) === "xx" ? "yy" : "xx");
    await TestValidator.error(`${title} tampered JWT invalid`)(async () => {
      await api.functional.auth.customer.validate.post.validateToken(connection, {
        body: { jwt: tampered } satisfies IShoppingMallAiCustomer.ValidateToken,
      });
    });
  }

  // 6. Clearly invalid token
  await TestValidator.error("validate with garbage token should fail")(async () => {
    await api.functional.auth.customer.validate.post.validateToken(connection, {
      body: { jwt: "garbage.invalid.token" } satisfies IShoppingMallAiCustomer.ValidateToken,
    });
  });

  // 7. (Skipped) Cannot deactivate/delete user in E2E env due to missing backend API.
}

