import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachment";
import type { IPageIAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate business link search for attachments when no business links exist for a given domain/target filter.
 *
 * This test ensures that when an administrator searches for business links for a freshly created attachment using filter criteria (domain, target_id) that have no matching records, the API returns a result with empty data, correct pagination values, and does not expose information about other business links or unrelated entities.
 *
 * Steps:
 * 1. Register an administrator account. Save credentials for later use (email, password hash, display name, status, role).
 * 2. Log in as the administrator, obtaining authentication headers/tokens for subsequent admin actions.
 * 3. Register a new attachment using the admin account. The created attachment's UUID will be the context for the business link search.
 * 4. As an administrator, perform a business link search on the attachment using target_domain and target_id filter values that ensure no links exist (since the attachment has just been created and no business links are associated yet).
 * 5. Validate the search returns a paginated result with an empty data array. Confirm pagination fields (e.g., current page, record count) are correct and that no extraneous or unauthorized business links are included.
 */
export async function test_api_attachment_business_links_search_no_result(
  connection: api.IConnection,
) {
  // 1. Register an administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = 'hashed-password-123'; // Mocked hash for test; in production, proper hash.
  const adminDisplayName = RandomGenerator.name();
  const registerResult = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
      display_name: adminDisplayName,
      status: 'active',
      role: 'superadmin',
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(registerResult);
  const authHeader = registerResult.setHeaders.Authorization;
  // Assign Authorization header to connection for admin actions
  connection.headers = { ...connection.headers, Authorization: authHeader };

  // 2. Log in as administrator (verifies login & issues token, even though not needed if registration returns token)
  const loginResult = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(loginResult);
  // (header is likely the same, but could overwrite for token freshness)
  connection.headers = { ...connection.headers, Authorization: loginResult.setHeaders.Authorization };

  // 3. Register a new attachment as this admin
  const attachmentInput: IShoppingMallAiAttachment.ICreate = {
    uploaded_by_id: registerResult.id,
    filename: RandomGenerator.alphaNumeric(10),
    mime_type: 'application/pdf',
    file_uri: 'https://cdn.example.com/test-attachment.pdf',
    file_size: 1024,
    business_domain: 'test_domain',
    retention_policy_code: 'standard',
    legal_hold: false,
    access_acl: '{}',
  };
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: attachmentInput,
  });
  typia.assert(attachment);

  // 4. Search for business links with a target_domain and a random target_id that do not match any link
  const nonExistentDomain = 'unused_domain';
  const nonExistentTargetId = typia.random<string & tags.Format<'uuid'>>();
  const searchResult = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.search(connection, {
    attachmentId: attachment.id,
    body: {
      target_domain: nonExistentDomain,
      target_id: nonExistentTargetId,
      page: 1,
      limit: 10,
    } satisfies IAttachment.AttachmentBusinessLink.IRequest,
  });
  typia.assert(searchResult);
  // 5. Validate that the result is empty and pagination is correct
  TestValidator.equals('Empty link search result')(searchResult.data)([]);
  TestValidator.equals('Pagination page')(searchResult.pagination.current)(1);
  TestValidator.equals('Pagination limit')(searchResult.pagination.limit)(10);
  TestValidator.equals('Total records')(searchResult.pagination.records)(0);
  TestValidator.equals('Total pages')(searchResult.pagination.pages)(0);
}

