import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachment";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate successful update of an attachment-business link (domain/target/actor).
 *
 * This scenario ensures that an administrator can update the properties of an attachment-business link – specifically, domain, target, and/or actor (linked_by_id) – and that such metadata changes are reflected correctly for compliance and auditing. All business integrity, referential, and permission rules must be respected throughout the workflow.
 *
 * Steps:
 * 1. Register a new administrator and log in. Authenticate to receive Authorization header for subsequent operations.
 * 2. Register a new attachment via the administrator API (simulate upload, metadata registration only). Capture the returned attachment's id and uploaded_by_id for provenance.
 * 3. With the attachment, create an initial business link associating it to a business domain and target (e.g., product, order, evidence) and record the admin as the actor (linked_by_id).
 * 4. Update the attachment-business link: supply new values for at least one of target_domain, target_id, or linked_by_id via the update API. Use new, randomly generated but valid values (simulate realistic update scenario, e.g., domain correction, target swap, actor reassignment).
 * 5. Assert the response reflects all updates: updated domain, target, and/or actor is shown in returned object. Check that audit/control fields like id, attachment_id, created_at remain unchanged, but updated properties match the request (if supplied).
 * 6. (Business: If system supports audit logs, ensure update is tracked, but as direct log API access is not detailed in provided SDK, limit test to returned object verification.)
 */
export async function test_api_attachment_business_link_update_success(connection: api.IConnection) {
  // 1. Register administrator
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphabets(16);

  // Use 'active' status and a role such as 'superadmin' for full permissions
  const adminRegistration = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
      display_name: RandomGenerator.name(),
      status: "active",
      role: "superadmin",
    },
  });
  typia.assert(adminRegistration);
  // Set authorization header using registration result
  connection.headers = { ...connection.headers, ...adminRegistration.setHeaders };

  // 2. Login as administrator (redundant if registration provides credentials)
  const adminLogin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
    },
  });
  typia.assert(adminLogin);
  connection.headers = { ...connection.headers, ...adminLogin.setHeaders };

  // 3. Create an attachment
  const attachmentCreate = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      // uploaded_by_id is populated by backend; fill with admin id for simulation, mimicking real principal context
      uploaded_by_id: adminLogin.id,
      filename: `${RandomGenerator.alphabets(8)}.jpg`,
      mime_type: "image/jpeg",
      file_uri: `https://cdn.example.com/${RandomGenerator.alphaNumeric(10)}.jpg`,
      file_size: 1024,
      business_domain: "product_image",
      retention_policy_code: "standard",
      legal_hold: false,
      access_acl: "{\"admins\":[\"*\"]}",
    },
  });
  typia.assert(attachmentCreate);

  // 4. Create an attachment-business link
  const businessLink = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.create(connection, {
    attachmentId: attachmentCreate.id,
    body: {
      target_domain: "product",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      linked_by_id: adminLogin.id,
    },
  });
  typia.assert(businessLink);

  // 5. Update the business link: change target_domain and/or target_id and/or linked_by_id
  const updatedData = {
    target_domain: "evidence",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    linked_by_id: adminLogin.id,
  };
  const updatedLink = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.update(connection, {
    attachmentId: attachmentCreate.id,
    attachmentBusinessLinkId: businessLink.id,
    body: updatedData,
  });
  typia.assert(updatedLink);

  // 6. Assert updated properties
  TestValidator.equals("attachment id matches")(updatedLink.attachment_id)(attachmentCreate.id);
  TestValidator.equals("business link id matches")(updatedLink.id)(businessLink.id);
  TestValidator.equals("target domain updated")(updatedLink.target_domain)(updatedData.target_domain);
  TestValidator.equals("target id updated")(updatedLink.target_id)(updatedData.target_id);
  TestValidator.equals("linked_by_id updated")(updatedLink.linked_by_id)(updatedData.linked_by_id);
  // Audit fields remain unchanged (created_at exists, not compared here)
}

