 * This test covers a full admin attachment business link workflow, from privileged access to audit-level linkage and search.
 * It ensures retrieval works with filters, pagination, compliance, and business domain distinctions.
 *
 * Steps:
 * 1. Register a new administrator with audit/search privileges (and login).
 * 2. Create a new attachment record (file metadata, business domain, retention, etc.).
 * 3. Add several business links (for different target_domain and target_id, e.g., 'product', 'order').
 * 4. Retrieve business links for that attachment, with/without domain/target_id filters, and with pagination/limit settings.
 * 5. Assert that only authorized business links are returned for the administrator, in correct order and count.
 * 6. Validate metadata and linkage objects for compliance/audit fields.
 * 7. Optionally, test search when filtered by domain or target_id, and edge cases such as over-limit pages.
 */
export async function test_api_attachment_business_links_list_by_domain_success(connection: api.IConnection) {
  // 1. Register a new administrator
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12);
  const adminDisplayName: string = RandomGenerator.name();
  const admin: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
      display_name: adminDisplayName,
      status: "active",
      role: "superadmin",
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(admin);
  connection.headers = { ...(connection.headers ?? {}), ...(admin.setHeaders) };

  // 2. Login as the admin (test login endpoint and new session)
  const login: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(login);
  connection.headers = { ...(connection.headers ?? {}), ...(login.setHeaders) };

  // 3. Create a new attachment (for link association)
  const attachment: IShoppingMallAiAttachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      uploaded_by_id: admin.id,
      filename: "e2e-test-file.png",
      mime_type: "image/png",
      file_uri: "https://static.example.com/e2e-test-file.png",
      file_size: 1048576,
      business_domain: "product_image",
      retention_policy_code: "standard",
      legal_hold: false,
      access_acl: "{\"admin\":true}",
    } satisfies IShoppingMallAiAttachment.ICreate,
  });
  typia.assert(attachment);

  // 4. Add multiple business links with distinct target domains/ids
  const domains = ["product", "order", "evidence"];
  const targets = ArrayUtil.repeat(domains.length)(() => typia.random<string & tags.Format<"uuid">>());
  const businessLinks: IAttachment.AttachmentBusinessLink[] = [];
  for (let i = 0; i < domains.length; ++i) {
    const link = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.create(connection, {
      attachmentId: attachment.id,
      body: {
        target_domain: domains[i],
        target_id: targets[i],
        linked_by_id: admin.id,
      } satisfies IAttachment.AttachmentBusinessLink.ICreate,
    });
    typia.assert(link);
    businessLinks.push(link);
  }

  // 5. Retrieve ALL links for this attachment (no filter)
  const allLinksResult = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.search(connection, {
    attachmentId: attachment.id,
    body: {}
  });
  typia.assert(allLinksResult);
  TestValidator.equals("total record count")(allLinksResult.pagination.records)(domains.length);
  TestValidator.equals("returned array")(allLinksResult.data.length)(domains.length);

  // 6. Search by domain filter (e.g., 'order')
  const orderLinkResult = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.search(connection, {
    attachmentId: attachment.id,
    body: { target_domain: "order" },
  });
  typia.assert(orderLinkResult);
  TestValidator.equals("order domain filtered count")(orderLinkResult.data.length)(1);
  TestValidator.equals("filtered domain")(orderLinkResult.data[0].target_domain)("order");

  // 7. Search by specific target_id
  const evidenceTargetId = targets[2];
  const evidenceResult = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.search(connection, {
    attachmentId: attachment.id,
    body: { target_id: evidenceTargetId },
  });
  typia.assert(evidenceResult);
  TestValidator.equals("filtered target_id")(evidenceResult.data.length)(1);
  TestValidator.equals("filtered target id matches")(evidenceResult.data[0].target_id)(evidenceTargetId);

  // 8. Search with pagination (limit=1, page=2)
  const paginated = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.search(connection, {
    attachmentId: attachment.id,
    body: { page: 2, limit: 1 },
  });
  typia.assert(paginated);
  TestValidator.equals("pagination current")(paginated.pagination.current)(2);
  TestValidator.equals("pagination limit")(paginated.pagination.limit)(1);
  TestValidator.equals("pagination total records")(paginated.pagination.records)(domains.length);
  TestValidator.equals("paginated array length")(paginated.data.length)(1);

  // 9. All business links must reference this attachment and be made/linked by admin for audit
  for (const link of allLinksResult.data) {
    TestValidator.equals("attachment id match")(link.attachment_id)(attachment.id);
    TestValidator.equals("linked by admin")(link.linked_by_id)(admin.id);
    TestValidator.predicate("target domain is valid")(
      domains.includes(link.target_domain),
    );
    // check field presence, types, and compliance
    typia.assert(link);
  }
}

