import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IShoppingMallAiAttachmentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachmentVersion";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate that administrator cannot soft-delete an attachment version if it is under legal hold (compliance constraint).
 *
 * Business context:
 * In this AI-powered shopping mall system, files/attachments can be placed under legal hold due to compliance or regulatory requirements. Once an attachment or its version is under legal hold, it must not be deleted—attempts must be rejected by the system. This is especially critical for legal evidence, regulatory records, or active investigations.
 *
 * Steps:
 * 1. Create a new administrator (register, and authenticate)
 * 2. Register a new attachment using this administrator
 * 3. Add a version to this attachment, simulating a file update, ensuring the version is placed under legal hold
 * 4. Attempt to soft-delete this attachment version as the administrator
 * 5. Confirm that deletion is forbidden (system throws an error), deletion does not occur, and this is logged for compliance review
 *
 * Additional business rules:
 * - Legal hold must strictly prevent logical deletion for all roles
 * - Compliance requires such attempts to be logged/denied (a runtime error is expected)
 * - The attachment version must remain accessible for ongoing/legal review even after failed deletion attempts
 */
export async function test_api_attachment_version_delete_legal_hold_forbidden(connection: api.IConnection) {
  // 1. Register and authenticate as a new administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const passwordHash = adminPassword; // For test, use plaintext for simplicity
  const displayName = RandomGenerator.name();
  const adminReg = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: passwordHash,
      display_name: displayName,
      status: "active",
      role: "superadmin",
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(adminReg);

  // Immediately login to update connection's authorization
  const adminLogin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: passwordHash,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(adminLogin);

  // 2. Register new attachment (legal_hold = true)
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      uploaded_by_id: adminReg.id,
      filename: RandomGenerator.alphabets(8) + ".pdf",
      mime_type: "application/pdf",
      file_uri: `https://cdn.test/${RandomGenerator.alphaNumeric(32)}`,
      file_size: typia.random<number & tags.Type<"int32">>(),
      business_domain: "evidence",
      retention_policy_code: "evidence",
      legal_hold: true, // Place under legal hold on creation
      access_acl: '{"roles":["administrator"]}',
    } satisfies IShoppingMallAiAttachment.ICreate,
  });
  typia.assert(attachment);

  // 3. Register new version for the attachment
  const version = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.createVersion(connection, {
    attachmentId: attachment.id,
    body: {
      modified_by_id: adminReg.id,
      file_uri: attachment.file_uri,
      file_size: attachment.file_size,
      diff_comment: "Initial upload, legal hold active.",
    } satisfies IShoppingMallAiAttachmentVersion.ICreate,
  });
  typia.assert(version);

  // 4. Attempt to soft-delete version (should fail due to legal hold)
  await TestValidator.error("deletion forbidden when legal hold is active")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.erase(
        connection,
        {
          attachmentId: attachment.id,
          attachmentVersionId: version.id,
        }
      );
    }
  );

  // 5. No SDK GET endpoint for attachment/version provided, so cannot re-fetch, but previous assertions suffice for compliance scenario.
}

