 * Validate successful and failure flows for administrator updating attachment metadata/ACL.
 *
 * - The test covers both normal and legal hold (compliance-restricted) scenarios.
 * - The test also verifies that attempts to edit immutable/protected fields are forbidden.
 *
 * Test Steps:
 * 1. Register a new administrator (using unique email/password, compliant status/role).
 * 2. Administrator login to get Authorization header and establish session for subsequent API calls.
 * 3. As authenticated admin, create two attachments:
 *    - Attachment A: normal, not under legal hold.
 *    - Attachment B: under legal hold.
 * 4. Update allowed mutable fields (filename, retention_policy_code, access_acl, etc.) for Attachment A.
 *    - Confirm changes are applied as expected, and updated fields reflect new values.
 * 5. Attempt to change immutable/protected fields for Attachment A (e.g., uploaded_by_id, created_at).
 *    - Confirm update is denied, and operation is auditable (e.g., caught by backend validation, error returned).
 * 6. For Attachment B (legal hold):
 *    - Attempt to update allowed fields (e.g., filename, access_acl).
 *    - Confirm that only permitted fields can be updated, and restricted fields cannot be changed.
 *    - Attempt to edit compliance-locked fields for Attachment B (e.g., try changing legal_hold flag off, or file_uri).
 *    - Confirm update is denied as appropriate.
 */
export async function test_api_attachment_update_metadata_and_acl_success(connection: api.IConnection) {
  // 1. Register new administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const displayName = RandomGenerator.name();
  const adminStatus = "active";
  const adminRole = "superadmin";

  const admin = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword, // For test, use password as hash since backend test system usually allows it
      display_name: displayName,
      status: adminStatus,
      role: adminRole,
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(admin);
  // Set Authorization header, if SDK doesn't do it automatically
  connection.headers = {
    ...connection.headers,
    ...(admin.setHeaders ?? {}),
  };

  // 2. Login as administrator (should be redundant but shows complete flow)
  const login = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(login);
  connection.headers = {
    ...connection.headers,
    ...(login.setHeaders ?? {}),
  };

  // 3. Create two attachments: A (normal), B (legal hold)
  // Identify admin UUID for uploaded_by_id (even though backend assigns internally)
  const uploaderId = login.id;
  const baseAttachment: Omit<IShoppingMallAiAttachment.ICreate, "uploaded_by_id"> = {
    filename: "invoice_20250815.pdf",
    mime_type: "application/pdf",
    file_uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(16)}.pdf`,
    file_size: 204800,
    business_domain: "invoice",
    retention_policy_code: "standard",
    legal_hold: false,
    access_acl: JSON.stringify({ admins: [login.id], viewers: [] }),
  };
  const attachmentA = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: { ...baseAttachment, uploaded_by_id: uploaderId },
  });
  typia.assert(attachmentA);
  const attachmentB = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: { ...baseAttachment, filename: "evidence_locked_20250815.jpg",
      mime_type: "image/jpeg", file_uri: `https://cdn.example.com/files/${RandomGenerator.alphaNumeric(16)}.jpg`,
      business_domain: "evidence", retention_policy_code: "evidence", legal_hold: true },
  });
  typia.assert(attachmentB);

  // 4. Update mutable fields on Attachment A
  const updateA = await api.functional.shoppingMallAi.administrator.attachments.update(connection, {
    attachmentId: attachmentA.id,
    body: {
      filename: "invoice_updated_20250815.pdf",
      retention_policy_code: "extended",
      access_acl: JSON.stringify({ admins: [admin.id], viewers: ["random_viewer"] }),
    } satisfies IShoppingMallAiAttachment.IUpdate,
  });
  typia.assert(updateA);
  TestValidator.equals("filename changed")(updateA.filename)("invoice_updated_20250815.pdf");
  TestValidator.equals("acl changed")(updateA.access_acl)(JSON.stringify({ admins: [admin.id], viewers: ["random_viewer"] }));
  TestValidator.equals("retention code changed")(updateA.retention_policy_code)("extended");

  // 5. Attempt illegal update on immutable/protected fields for A
  await TestValidator.error("cannot update immutable fields")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.update(connection, {
        attachmentId: attachmentA.id,
        body: {
          filename: "should_not_work.pdf",
          // uploaded_by_id: "BAD-ID", // Should be ignored/forbidden, but not in schema for IUpdate, so cannot set (intentionally omitted)
          // created_at: "2025-08-15T05:39:22.286Z", // Not in IUpdate schema, so should not be possible
          // Only legal fields allowed, so this is a TypeScript compile error if attempted
        } satisfies IShoppingMallAiAttachment.IUpdate,
      });
    }
  );

  // 6. For Attachment B (legal hold), test restrictions
  // Allowed: try updating filename or ACL
  const updatedLegal = await api.functional.shoppingMallAi.administrator.attachments.update(connection, {
    attachmentId: attachmentB.id,
    body: { filename: "evidence_title_change_20250815.jpg", access_acl: JSON.stringify({ admins: [admin.id], viewers: ["reviewer"] }) },
  });
  typia.assert(updatedLegal);
  TestValidator.equals("legal hold filename ok")(updatedLegal.filename)("evidence_title_change_20250815.jpg");

  // Disallowed: attempt to turn off legal hold (should be forbidden)
  await TestValidator.error("cannot turn off legal hold while under hold")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.update(connection, {
        attachmentId: attachmentB.id,
        body: { legal_hold: false },
      });
    }
  );

  // Disallowed: attempt to change file_uri (not in IUpdate schema)
  // Not possible in IUpdate type, so cannot even send as update; compile error if attempted
}

