/**
 * Validate that a non-administrator (seller) user cannot access attachment version search in the admin domain (permission denied scenario).
 *
 * This test ensures strict role enforcement and verifies that even if the resource (attachment) exists, a seller cannot use administrator-only endpoints for version searching/auditing.
 *
 * Workflow:
 * 1. Register as a seller (non-admin user)
 * 2. Login as the seller to obtain valid authentication tokens
 * 3. Create a new attachment within the seller scope (this ensures an actual attachment for downstream use)
 * 4. As the seller, attempt to call the administrator endpoint to search attachment versions for the newly created attachment
 * 5. Verify that the response is a permission-denied error (typically HTTP 403/401 or similar), confirming that access is not granted to non-admins
 */
export async function test_api_attachment_version_search_permission_denied(connection: api.IConnection) {
  // 1. Register seller (non-admin user)
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Abcd1234!";
  const sellerBusinessNo = RandomGenerator.alphaNumeric(10);
  const sellerDisplayName = RandomGenerator.alphaNumeric(8);

  const sellerRegRes = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      business_registration_number: sellerBusinessNo,
      display_name: sellerDisplayName,
    } satisfies ISellerAuthRegisterRequest,
  });
  typia.assert(sellerRegRes);
  const sellerId = sellerRegRes.seller.id;

  // 2. Login as seller
  const loginRes = await api.functional.auth.seller.login.post(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies ISellerAuthLoginRequest,
  });
  typia.assert(loginRes);

  // 3. Create a new attachment as seller
  const attachment = await api.functional.shoppingMallAi.seller.attachments.post(connection, {
    body: {
      uploaded_by_id: sellerId, // will be ignored server-side
      filename: RandomGenerator.alphaNumeric(12) + ".jpg",
      mime_type: "image/jpeg",
      file_uri: "https://cdn.example.com/" + RandomGenerator.alphaNumeric(16),
      file_size: typia.random<number & tags.Type<"int32">>(),
      business_domain: "product_image",
      retention_policy_code: "standard",
      legal_hold: false,
      access_acl: "{\"roles\":[\"seller\"]}",
    } satisfies IShoppingMallAiAttachment.ICreate,
  });
  typia.assert(attachment);

  // 4. Attempt to access administrator-only attachment version search as seller (should fail)
  await TestValidator.error("seller cannot use admin version endpoint")(
    async () => {
      await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.patchByAttachmentid(connection, {
        attachmentId: attachment.id,
        body: {
          page: 1,
          limit: 10,
        } satisfies IShoppingMallAiAttachmentVersion.IRequest,
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";

/**
 * E2E test for seller registration required field validation.
 *
 * This test verifies that the POST /auth/seller/register endpoint enforces all required fields. It attempts to register a new seller while omitting each required field in turn and ensures that a runtime validation error is triggered by the API. TypeScript type system prevents compile-time-incomplete objects, so each omission is performed at the runtime boundary only, and no type bypasses are used.
 *
 * Steps:
 * 1. Prepare a valid seller registration data object (all four required fields).
 * 2. For each required field (email, password, business_registration_number, display_name), create a payload omitting one field.
 * 3. Attempt to register with this incomplete payload and assert that an error occurs for each missing required field.
 *
 * No error message or error type validation is performed—only the occurrence of an error is verified. The test complies with E2E and typesafety standards by never using 'any', 'as any', or '@ts-ignore', and by not attempting to test at the type error level (which is impossible in strict TypeScript).
 */
export async function test_api_seller_registration_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Prepare valid registration data for a new seller
  const validRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    business_registration_number: RandomGenerator.alphaNumeric(10),
    display_name: RandomGenerator.name(),
  } satisfies ISellerAuthRegisterRequest;

  // 2. Omit 'email' field and verify registration fails
  await TestValidator.error("missing email should fail")(async () => {
    const { email, ...body } = validRequest;
    await api.functional.auth.seller.register.signUp(connection, { body });
  });

  // 3. Omit 'password' field and verify registration fails
  await TestValidator.error("missing password should fail")(async () => {
    const { password, ...body } = validRequest;
    await api.functional.auth.seller.register.signUp(connection, { body });
  });

  // 4. Omit 'business_registration_number' field and verify registration fails
  await TestValidator.error("missing business_registration_number should fail")(async () => {
    const { business_registration_number, ...body } = validRequest;
    await api.functional.auth.seller.register.signUp(connection, { body });
  });

  // 5. Omit 'display_name' field and verify registration fails
  await TestValidator.error("missing display_name should fail")(async () => {
    const { display_name, ...body } = validRequest;
    await api.functional.auth.seller.register.signUp(connection, { body });
  });
}

