import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";

/**
 * 테스트 목적: 셀러 회원가입의 정상 처리와 이메일 중복 방지 검증
 *
 * 본 테스트는 신규 셀러가 정상적인 정보로 회원가입을 시도할 경우 성공적으로 토큰이 발급되고, 같은 이메일로 재시도할 경우 중복 이메일 오류가 발생하는지 검증합니다.
 *
 * 테스트 단계:
 * 1. 임의로 생성된 유효한 이메일, 비밀번호, 사업자 등록번호, 판매자명으로 셀러 회원가입을 시도합니다.
 *    - 성공적으로 회원가입이 처리되고 JWT 토큰이 setHeaders.Authorization에 포함되어 응답되는지 확인합니다.
 * 2. 동일한 이메일 주소를 사용하여 다시 셀러 회원가입을 시도합니다.
 *    - API가 이메일 중복 오류를 반환하는지, 신규 셀러 계정이 생성되지 않는지를 확인합니다.
 */
export async function test_api_seller_registration_success_and_duplicate_email(
  connection: api.IConnection,
) {
  // 1. 셀러 회원가입 정상 처리
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12); // 랜덤 12자리
  const business_registration_number = RandomGenerator.alphaNumeric(10); // 10자리, 실제 사업자번호 패턴 요구 시 수정 필요
  const display_name = RandomGenerator.name();

  const sellerResponse = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email,
      password,
      business_registration_number,
      display_name,
    } satisfies ISellerAuthRegisterRequest,
  });
  typia.assert(sellerResponse);
  // JWT 토큰이 정상적으로 발급되고 셀러 정보가 올바르게 반환되는지 확인
  TestValidator.predicate("JWT 토큰이 발급됨")(typeof sellerResponse.setHeaders?.Authorization === "string" && sellerResponse.setHeaders?.Authorization.length > 0);
  TestValidator.equals("회원가입된 이메일 확인")(sellerResponse.seller.email)(email);
  TestValidator.equals("등록된 사업자등록번호 확인")(sellerResponse.seller.business_registration_number)(business_registration_number);
  TestValidator.equals("등록된 표시명 확인")(sellerResponse.seller.display_name)(display_name);

  // 2. 동일 이메일로 재가입 시도 -> 중복 오류 검증
  await TestValidator.error("중복 이메일로 회원가입 시도 시 오류 발생")(
    async () => {
      await api.functional.auth.seller.register.signUp(connection, {
        body: {
          email, // 동일 이메일로 시도
          password: RandomGenerator.alphaNumeric(12),
          business_registration_number: RandomGenerator.alphaNumeric(10),
          display_name: RandomGenerator.name(),
        } satisfies ISellerAuthRegisterRequest,
      });
    },
  );
}

