/**
 * Validate seller JWT access token including simulation of inactive account case.
 *
 * This test ensures that a valid seller JWT token is correctly validated and that status flags properly reflect account state. The flow begins with registering a new seller, logging in to get a fresh JWT token, and validating it (should pass and status is 'active').
 *
 * To simulate business/account lifecycle and edge cases:
 * - Since the test cannot call a direct deactivation endpoint (not provided), we acknowledge this step cannot be executed in the test code.
 * - We document that a token validation following deactivation would be expected to return isValid: false or status: 'withdrawn'/'suspended', but such a change can't be triggered directly in the E2E test using available endpoints.
 *
 * Steps:
 * 1. Register a new seller (random credentials)
 * 2. Log in as the seller to get JWT token
 * 3. Validate the token and check the response fields for validity and 'active' status
 * 4. (OUT OF SCOPE) Deactivate seller and test token validation again (cannot implement
 *    due to missing API; left as test comment for future extension)
 */
export async function test_api_seller_token_validation_success_and_inactive_account(
  connection: api.IConnection,
) {
  // 1. Register a new seller
  const sellerRegistration = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "testPassword!123",
      business_registration_number: RandomGenerator.alphaNumeric(10),
      display_name: RandomGenerator.name(),
    },
  });
  typia.assert(sellerRegistration);
  const { email, display_name, status, business_registration_number } = sellerRegistration.seller;
  TestValidator.equals("seller status active at register")(status)("active");

  // 2. Seller logs in to get JWT
  const login = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: email,
      password: "testPassword!123",
    },
