    body: { token: jwt },
  });
  typia.assert(validation);
  TestValidator.equals("token valid")(validation.isValid)(true);
  TestValidator.equals("token seller matches")(validation.sellerId)(sellerRegistration.seller.id);
  TestValidator.equals("status is active")(validation.status)("active");
  TestValidator.equals("error is null")(validation.error)(null);

  // 4. Simulate deactivation (out of scope)
  // If account deactivation API was available =>
  //    deactivate seller
  //    validateToken (expect isValid: false and/or status != 'active')
  // This cannot be implemented due to missing endpoint, so leave as future TODO.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISellerAuthRegisterRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthRegisterRequest";
import type { ISellerAuthWithSetHeaders } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthWithSetHeaders";
import type { ISellerAuthLoginRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthLoginRequest";
import type { ISellerAuthTokenResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthTokenResponse";
import type { ISellerAuthPasswordChangeRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthPasswordChangeRequest";
import type { ISellerAuthPasswordChangeResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/ISellerAuthPasswordChangeResponse";

/**
 * Validate the process of changing a seller's password, including both successful and failure cases.
 *
 * Business context: Password management is a critical security feature for sellers. This test covers both a valid password change as well as validation against incorrect credential input. The scenario ensures secure handling of password changes and proper feedback for error conditions. Only authenticated sellers should be able to perform this action, and the operation must audit input and enforce current password validation before allowing changes.
 *
 * Step-by-step process:
 * 1. Register a new seller using unique credentials (email, password, business registration number, display name)
 * 2. Log in the seller to obtain a valid session/JWT
 * 3. Attempt to change the password by providing the correct current password and a new strong password – expect success
 * 4. Attempt to change the password again, now providing an incorrect (old/invalid) current password – expect failure, with a proper error returned
 * 5. Confirm both the successful and failed outcomes according to the response type and expected side effects
 * 6. Optionally, verify login works with new password and fails with the old one to fully confirm update
 */
export async function test_api_seller_password_change_success_and_incorrect_current_password(
  connection: api.IConnection,
) {
  // 1. Register a new seller
  const uniqueEmail: string = typia.random<string & tags.Format<"email">>();
  const originalPassword: string = RandomGenerator.alphaNumeric(12);
  const businessRegNum: string = RandomGenerator.alphaNumeric(10);
  const displayName: string = RandomGenerator.name();

  const signUpOutput = await api.functional.auth.seller.register.signUp(connection, {
    body: {
      email: uniqueEmail,
      password: originalPassword,
      business_registration_number: businessRegNum,
      display_name: displayName,
    } satisfies ISellerAuthRegisterRequest,
  });
  typia.assert(signUpOutput);

  // 2. Log in as the seller to get token/session
  const loginOutput = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: uniqueEmail,
      password: originalPassword,
    } satisfies ISellerAuthLoginRequest,
  });
  typia.assert(loginOutput);

  // 3. Change password with correct current password (should succeed)
  const newPassword: string = RandomGenerator.alphaNumeric(14);
  const pwChangeOutput = await api.functional.auth.seller.password.changePassword(connection, {
    body: {
      currentPassword: originalPassword,
      newPassword: newPassword,
    } satisfies ISellerAuthPasswordChangeRequest,
  });
  typia.assert(pwChangeOutput);
  TestValidator.equals("password change succeeded")(pwChangeOutput.success)(true);

  // 4. Attempt to change password *again* using the now-invalid (original) password (should fail)
  const anotherPassword: string = RandomGenerator.alphaNumeric(13);
  await TestValidator.error("incorrect current password should fail")(async () => {
    await api.functional.auth.seller.password.changePassword(connection, {
      body: {
        currentPassword: originalPassword, // Now incorrect after update
        newPassword: anotherPassword,
      } satisfies ISellerAuthPasswordChangeRequest,
    });
  });

  // 5. Final assertion: login works with new password and fails with old password
  //    (Full password update confirmation)
  const reLogin = await api.functional.auth.seller.login.signIn(connection, {
    body: {
      email: uniqueEmail,
      password: newPassword,
    } satisfies ISellerAuthLoginRequest,
  });
  typia.assert(reLogin);

  await TestValidator.error("login with old password should fail")(async () => {
    await api.functional.auth.seller.login.signIn(connection, {
      body: {
        email: uniqueEmail,
        password: originalPassword,
      } satisfies ISellerAuthLoginRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * E2E test for administrator registration (success and validation error).
 *
 * This test validates the onboarding process for new administrators, ensuring both successful registration and correct enforcement of validation rules on failure scenarios.
 *
 * Steps:
 * 1. Register with valid, unique details (email, password_hash, display_name, status, role); verify creation and JWT issuance.
 * 2. Attempt duplicate registration with the same email; expect duplicate constraint error.
 * 3. Attempt registration with invalid email format; expect validation error.
 * 4. Attempt registration with missing/empty required fields; expect validation error.
 */
export async function test_api_administrator_registration_success_and_validation_errors(connection: api.IConnection) {
  // 1. Register administrator with valid unique details
  const uniqueEmail = typia.random<string & tags.Format<"email">>();
  const validInput: IAdministrator.ICreate = {
    email: uniqueEmail,
    password_hash: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    status: "active",
    role: "superadmin",
  };
  const registration: IAdministrator.IWithAuthHeaders = await api.functional.auth.administrator.register.signUp(connection, { body: validInput });
  typia.assert(registration);
  TestValidator.equals("email matches input")(registration.email)(uniqueEmail);
  TestValidator.equals("role matches input")(registration.role)("superadmin");
  TestValidator.equals("status matches input")(registration.status)("active");
  TestValidator.predicate("Authorization header present")(typeof registration.setHeaders.Authorization === "string" && registration.setHeaders.Authorization.length > 0);

  // 2. Duplicate email registration should fail
  const duplicateInput: IAdministrator.ICreate = { ...validInput, display_name: RandomGenerator.name() };
  await TestValidator.error("duplicate email triggers validation failure")(async () => {
    await api.functional.auth.administrator.register.signUp(connection, { body: duplicateInput });
  });

  // 3. Invalid email format triggers validation error
  const invalidEmailInput: IAdministrator.ICreate = {
    ...validInput,
    email: "not-an-email",
    display_name: RandomGenerator.name(),
  };
  await TestValidator.error("invalid email format")(async () => {
    await api.functional.auth.administrator.register.signUp(connection, { body: invalidEmailInput });
  });

  // 4. Each required field as empty string triggers validation error
  const fieldVariants: IAdministrator.ICreate[] = [
    { ...validInput, email: "" },
    { ...validInput, password_hash: "" },
    { ...validInput, display_name: "" },
    { ...validInput, status: "" },
    { ...validInput, role: "" },
  ];
  for (const badInput of fieldVariants) {
    await TestValidator.error("required field missing or empty")(async () => {
      await api.functional.auth.administrator.register.signUp(connection, { body: badInput });
    });
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate successful administrator login for an active account.
 *
 * This test verifies that an administrator can successfully log in if their account
 * is registered with valid details and set to 'active' status.
 *
 * Steps:
 * 1. Register a new administrator with random valid email, password (hashed),
 *    display name, status='active', and a randomly generated role string.
 * 2. Attempt to log in using the registered email and password hash.
 * 3. Assert that authentication is successful and a valid JWT token is present
 *    in the response setHeaders field.
 */
export async function test_api_administrator_login_success_with_active_account(
  connection: api.IConnection,
) {
  // 1. Register a new administrator
  const email = typia.random<string & tags.Format<"email">>();
  const passwordHash = typia.random<string>();
  const displayName = RandomGenerator.name();
  const role = RandomGenerator.alphabets(8);
  const status = "active";

  const registered: IAdministrator.IWithAuthHeaders =
    await api.functional.auth.administrator.register.signUp(connection, {
      body: {
        email,
        password_hash: passwordHash,
        display_name: displayName,
        status,
        role,
      } satisfies IAdministrator.ICreate,
    });
  typia.assert(registered);
  TestValidator.equals("status is active")(registered.status)("active");
  TestValidator.equals("email matches")(registered.email)(email);
  TestValidator.equals("display name matches")(registered.display_name)(displayName);
  TestValidator.equals("role matches")(registered.role)(role);
  TestValidator.predicate("JWT token issued after registration")(
    typeof registered.setHeaders.Authorization === "string" &&
      registered.setHeaders.Authorization.startsWith("Bearer ") &&
      registered.setHeaders.Authorization.length > 20,
  );

  // 2. Attempt to login using the same credentials
  const login: IAdministrator.IWithAuthHeaders =
    await api.functional.auth.administrator.login.signIn(connection, {
      body: {
        email,
        password_hash: passwordHash,
      } satisfies IAdministrator.ILogin,
    });
  typia.assert(login);

  // 3. Assert successful authentication and JWT presence
  TestValidator.equals("login email matches")(login.email)(email);
  TestValidator.equals("account status after login")(login.status)("active");
  TestValidator.predicate("JWT token issued after login")(
    typeof login.setHeaders.Authorization === "string" &&
      login.setHeaders.Authorization.startsWith("Bearer ") &&
      login.setHeaders.Authorization.length > 20,
  );
}

