 * 1. Register a new administrator with valid credentials.
 * 2. Authenticate as the new administrator to obtain an access token.
 * 3. Attempt to change password using an incorrect current password and confirm an authentication error occurs.
 * 4. Re-authenticate with the original credentials to confirm password was not changed after failure.
 */
export async function test_api_administrator_change_password_fails_with_wrong_current_password(
  connection: api.IConnection,
) {
  // 1. Register a new administrator account
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPasswordHash: string = RandomGenerator.alphaNumeric(32);
  const displayName: string = RandomGenerator.alphabets(8);

  const signUp = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPasswordHash,
      display_name: displayName,
      status: "active",
      role: "superadmin",
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(signUp);
  TestValidator.equals("registered status is active")(signUp.status)("active");
  TestValidator.equals("registered role is superadmin")(signUp.role)("superadmin");
  TestValidator.equals("registered display_name matches")(signUp.display_name)(displayName);

  // 2. Log in with the same administrator credentials
  const login = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPasswordHash,
