import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCustomer";

/**
 * Validate customer JWT token handling and failure conditions.
 *
 * - Validates authentication session for customer JWT issued via register and login flow.
 * - Checks correct handling of valid, tampered, and expired/invalid tokens.
 * - Simulates backend deactivation state for user.
 *
 * Step-by-step:
 * 1. Generate a new unique email, password, and nickname.
 * 2. Register a new customer using the above credentials.
 * 3. Assert output type and extract the JWT token from setHeaders.Authorization.
 * 4. Immediately call login with same credentials to obtain a fresh JWT as well; validate this token too.
 * 5. For both tokens, call the validate endpoint, assert isValid = true, status = "active", userId matches, and expiration is in the future.
 * 6. Tamper each token (e.g., alter a character), use validate endpoint, and assert error is thrown.
 * 7. Use clearly invalid token (e.g., "garbage.invalid.token"), expect validation error.
 * 8. (System limitation: we cannot deactivate or delete user in test due to lack of API, so skip real status change.)
 * 9. All responses must be type-asserted.
 */
export async function test_api_customer_token_validation_active_and_invalid_token(connection: api.IConnection) {
  // 1. Generate registration info
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPass123!";
  const nickname = RandomGenerator.name();

  // 2. Register new customer and extract JWT
  const registration = await api.functional.auth.customer.register.signUp(connection, {
    body: { email, password, nickname } satisfies IShoppingMallAiCustomer.SignUp,
  });
  typia.assert(registration);
  const regJwt = registration.setHeaders.Authorization;
  TestValidator.predicate("JWT token issued by register")(typeof regJwt === "string" && regJwt.length > 10);

  // 3. Login to get a fresh JWT (should be different from registration JWT)
  const login = await api.functional.auth.customer.login.signIn(connection, {
    body: { email, password } satisfies IShoppingMallAiCustomer.SignIn,
  });
  typia.assert(login);
  const loginJwt = login.setHeaders.Authorization;
  TestValidator.predicate("JWT token issued by login")(typeof loginJwt === "string" && loginJwt.length > 10);

  // 4. Validate both tokens
  for (const [title, jwt] of [["register", regJwt], ["login", loginJwt]] as const) {
    const result = await api.functional.auth.customer.validate.validateToken(connection, {
      body: { jwt } satisfies IShoppingMallAiCustomer.ValidateToken,
    });
    typia.assert(result);
    TestValidator.predicate(`${title} token is valid`)(result.isValid === true);
    TestValidator.equals(`${title} token status active`)(result.status)("active");
    TestValidator.equals(`${title} user id matches`)(result.userId)(registration.id);
    TestValidator.predicate(`${title} exp in future`)(typeof result.exp === "number" && result.exp > Math.floor(Date.now() / 1000));
  }

  // 5. Tampered tokens: alter a character and expect error
  for (const [title, jwt] of [["register", regJwt], ["login", loginJwt]] as const) {
    const tampered = jwt.slice(0, -2) + (jwt.slice(-2) === "xx" ? "yy" : "xx");
    await TestValidator.error(`${title} tampered JWT invalid`)(async () => {
      await api.functional.auth.customer.validate.validateToken(connection, {
        body: { jwt: tampered } satisfies IShoppingMallAiCustomer.ValidateToken,
      });
    });
  }

  // 6. Clearly invalid token
  await TestValidator.error("validate with garbage token should fail")(async () => {
    await api.functional.auth.customer.validate.validateToken(connection, {
      body: { jwt: "garbage.invalid.token" } satisfies IShoppingMallAiCustomer.ValidateToken,
    });
  });

  // 7. (Skipped) Cannot deactivate/delete user in E2E env due to missing backend API.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiCustomer";

/**
 * Validate customer password change flow and proper error handling.
 *
 * This scenario tests the end-to-end workflow for a customer changing their password including registration, login, password update, and authentication verification. It covers both the main success case and several important error paths.
 *
 * Process steps:
 * 1. Register a new customer with unique email and password to create an isolated test account.
 * 2. Authenticate by logging in as that customer to obtain a valid JWT and test credentials.
 * 3. While authenticated, attempt to change the password by submitting the correct current password and a new randomly generated password.
 * 4. Validate the password change response is successful (changed: true, error: null).
 * 5. Attempt to log in using the new password and verify authentication is allowed.
 * 6. Attempt to log in with the old password and verify authentication is rejected (error response).
 * 7. While authenticated with the new password, attempt to change the password again but submit an incorrect current password.
 * 8. Assert that the change is rejected (changed: false, error is non-null).
 * 9. (Negative permission control) Ensure only authenticated customers can access password change: test as unauthenticated or non-customer (if feasible - not doable here, so skipped).
 *
 * All steps use well-formed schema-compliant DTOs, strict type safety, and validate both results and business logic.
 */
export async function test_api_customer_password_change_success_and_wrong_current_password(connection: api.IConnection) {
  // Step 1: Register new customer
  const signUpInput: IShoppingMallAiCustomer.SignUp = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    nickname: RandomGenerator.name(),
    mobile: RandomGenerator.mobile(),
    oauth_provider: null,
    provider_account_id: null,
  };

  const signUpResult = await api.functional.auth.customer.register.signUp(connection, { body: signUpInput });
  typia.assert(signUpResult);

  // Step 2: Log in as the customer
  const loginResult = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: signUpInput.email,
      password: signUpInput.password,
    },
  });
  typia.assert(loginResult);

  // Save credentials
  const customerEmail = signUpInput.email;
  const customerOldPassword = signUpInput.password;
  const customerNewPassword = RandomGenerator.alphaNumeric(15);

  // Step 3: Change password with correct current password (should succeed)
  const changePwSuccess = await api.functional.auth.customer.password.changePassword(connection, {
    body: {
      currentPassword: customerOldPassword,
      newPassword: customerNewPassword,
    },
  });
  typia.assert(changePwSuccess);
  TestValidator.equals("password changed")(changePwSuccess.changed)(true);
  TestValidator.equals("no error message")(changePwSuccess.error)(null);

  // Step 4: Authenticate with new password (should succeed)
  const loginWithNewPw = await api.functional.auth.customer.login.signIn(connection, {
    body: {
      email: customerEmail,
      password: customerNewPassword,
    },
  });
  typia.assert(loginWithNewPw);
  TestValidator.equals("email after pw change")(loginWithNewPw.email)(customerEmail);

  // Step 5: Authenticate with old password (should fail)
  await TestValidator.error("old password cannot login")(async () => {
    await api.functional.auth.customer.login.signIn(connection, {
      body: {
        email: customerEmail,
        password: customerOldPassword,
      },
    });
  });

  // Step 6: Attempt to change password with WRONG current password (should fail)
  const badChangePw = await api.functional.auth.customer.password.changePassword(connection, {
    body: {
      currentPassword: customerOldPassword + "x", // intentionally wrong
      newPassword: RandomGenerator.alphaNumeric(16),
    },
  });
  typia.assert(badChangePw);
  TestValidator.equals("password not changed")(badChangePw.changed)(false);
  TestValidator.predicate("error message on failure")(!!badChangePw.error);

  // Step 7: Negative role control SKIPPED (API surface only exposes customer endpoints)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IPageIShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validates advanced search, filter, and pagination for the attachment management API accessible to administrators.
 *
 * Business context:
 * - Attachments may include sensitive evidence, legal/compliance docs, and operational assets, which require correct ACL, legal hold, and business domain logic.
 * - Only authenticated administrators (e.g., superadmin) can use advanced search; authorization is paramount.
 *
 * Test steps:
 * 1. Register a new administrator, login, set Authorization header.
 * 2. Upload a diversified set of attachments (mix of legal hold, business domains, and filenames).
 * 3. As admin, search/filter:
 *    a. Verify basic pagination and result count.
 *    b. Exact/partial filename match semantics.
 *    c. Filter by uploader (admin id) & consistency.
 *    d. Filter for legal hold files, ensure only those returned.
 *    e. Filter by business domain.
 *    f. Query with non-existent filename, expect empty data.
 *    g. Confirm returned files are always permitted for the "superadmin".
 */
export async function test_api_attachment_search_success_filter_pagination_access_control(connection: api.IConnection) {
  // 1. Register administrator (who will be used as attachment uploader)
  const adminInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphaNumeric(32),
    display_name: RandomGenerator.name(),
    status: "active",
    role: "superadmin",
  } satisfies IAdministrator.ICreate;
  const register = await api.functional.auth.administrator.register.signUp(connection, { body: adminInput });
  typia.assert(register);
  connection.headers = { ...(connection.headers ?? {}), ...register.setHeaders };

  // 2. Upload a diverse set of attachments
  const adminId = register.id;
  const attachments: IShoppingMallAiAttachment[] = [];
  const sampleParams = [
    {
      filename: "invoice_A_001.pdf",
      business_domain: "invoice",
      retention_policy_code: "standard",
      legal_hold: false,
    },
    {
      filename: "product_image_main.png",
      business_domain: "product_image",
      retention_policy_code: "standard",
      legal_hold: false,
    },
    {
      filename: "legal_evidence_100.docx",
      business_domain: "evidence",
      retention_policy_code: "evidence",
      legal_hold: true,
    },
    {
      filename: "compliance_2021.xlsx",
      business_domain: "compliance_doc",
      retention_policy_code: "evidence",
      legal_hold: true,
    },
  ];
  for (const params of sampleParams) {
    const output = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
      body: {
        uploaded_by_id: adminId,
        filename: params.filename,
        mime_type: "application/octet-stream",
        file_uri: `https://mock.cdn/attachments/${RandomGenerator.alphaNumeric(10)}`,
        file_size: typia.random<number & tags.Type<"int32"> & tags.Minimum<1024> & tags.Maximum<32768>>(),
        business_domain: params.business_domain,
        retention_policy_code: params.retention_policy_code,
        legal_hold: params.legal_hold,
        access_acl: JSON.stringify({ allowed_roles: ["superadmin"] }),
      } satisfies IShoppingMallAiAttachment.ICreate,
    });
    typia.assert(output);
    attachments.push(output);
  }

  // Get non-legal/ legal_hold attachments for filter tests
  const [nonLegalAttachment] = attachments.filter(a => !a.legal_hold);
  const [legalAttachment] = attachments.filter(a => a.legal_hold);

  // 3.a. Pagination test: get first page (limit 2)
  let result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(result);
  TestValidator.equals("page size matches or is capped")(result.data.length)(Math.min(attachments.length, 2));
  TestValidator.equals("pagination: current=1")(result.pagination.current)(1);
  TestValidator.equals("pagination: correct limit")(result.pagination.limit)(2);

  // 3.b. Exact filename match
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 5, filename: sampleParams[0].filename },
  });
  typia.assert(result);
  TestValidator.equals("filename exact search")(result.data.length)(1);
  TestValidator.equals("filename exact match")(result.data[0].filename)(sampleParams[0].filename);

  // 3.b. Partial filename match
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, filename: "invoice" },
  });
  typia.assert(result);
  TestValidator.predicate("partial filename search includes invoice_A_001.pdf")(result.data.some(a => a.filename.includes("invoice")));

  // 3.c. Uploader id filter
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, uploader_id: adminId },
  });
  typia.assert(result);
  TestValidator.equals("all results: uploaded_by administrator")(result.data.every(a => a.uploaded_by_id === adminId))(true);

  // 3.d. Legal hold filter
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, legal_hold: true },
  });
  typia.assert(result);
  TestValidator.equals("all results: legal_hold is true")(result.data.every(a => a.legal_hold))(true);
  TestValidator.predicate("legal_hold: expected file present")(result.data.some(a => a.filename === legalAttachment.filename));

  // 3.e. Business domain filter ("invoice")
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, business_domain: "invoice" },
  });
  typia.assert(result);
  TestValidator.predicate("all business_domain: invoice")(result.data.every(a => a.business_domain === "invoice"));

  // 3.f. Non-existent filename filter - expect empty data
  result = await api.functional.shoppingMallAi.administrator.attachments.search(connection, {
    body: { page: 1, limit: 10, filename: "non_existent_test_file_xyz" },
  });
  typia.assert(result);
  TestValidator.equals("no matches for non-existent filename")(result.data.length)(0);
}

