 *
 * This test ensures strict enforcement of domain separation and compliance rules for seller attachment registration in the AI shopping mall:
 *
 * 1. Register a new seller and authenticate as that seller.
 * 2. Attempt to POST an attachment with a business_domain value that is known to be restricted (such as 'compliance_doc' or 'legal_evidence').
 * 3. Attempt to POST an attachment with legal_hold: true (which is not allowed for sellers).
 * 4. For both cases, verify that the API correctly rejects the operation by throwing an error.
 */
export async function test_api_attachment_create_by_seller_forbidden_domain_failure(
  connection: api.IConnection,
) {
