/**
 * Validate retrieval of an attachment version's full metadata and audit fields as administrator.
 *
 * This test ensures:
 * - Admins can fetch all compliance/audit details of a specific attachment version
 * - All necessary fields are correct and complete (UUIDs, actors, timestamps, legal/deletion flags)
 * - Access control strictly enforces admin privilege for this endpoint
 * - The compliance policy for active, deleted, and legally flagged versions is honored
 *
 * Steps:
 * 1. Register a new administrator for the test
 * 2. Login as the administrator
 * 3. Register a new attachment (as admin)
 * 4. Register a new version for that attachment
 * 5. Retrieve the attachment version's metadata via the admin-only endpoint
 * 6. Verify all metadata, audit, and compliance fields are present and match expectations
 */
export async function test_api_attachment_version_details_success(connection: api.IConnection) {
  // 1. Register a new administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPasswordHash = RandomGenerator.alphaNumeric(32);
  const displayName = RandomGenerator.name();
  const status = "active";
  const role = "superadmin";
  const registerResp = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPasswordHash,
      display_name: displayName,
      status,
      role,
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(registerResp);
  TestValidator.equals("account status is active")(registerResp.status)(status);

  // 2. Login as the administrator
  const loginResp = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPasswordHash,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(loginResp);
  TestValidator.equals("login admin ID matches register")(loginResp.id)(registerResp.id);
  TestValidator.equals("login status is active")(loginResp.status)(status);

  // 3. Register a new attachment as admin
  const attachmentCreateBody = {
    uploaded_by_id: loginResp.id,
    filename: `testfile-attachment.txt`,
    mime_type: "text/plain",
    file_uri: `/test/uploads/testfile.txt`,
    file_size: 12345,
    business_domain: "evidence",
    retention_policy_code: "standard",
    legal_hold: false,
    access_acl: JSON.stringify({ allow: [role] }),
  } satisfies IShoppingMallAiAttachment.ICreate;
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: attachmentCreateBody,
  });
  typia.assert(attachment);
  TestValidator.equals("attachment uploaded_by_id matches admin")(attachment.uploaded_by_id)(loginResp.id);
  TestValidator.equals("deletion flag false")(attachment.deleted)(false);
  TestValidator.equals("legal_hold false")(attachment.legal_hold)(false);

  // 4. Register a new version (first version) for this attachment
  const versionBody = {
    modified_by_id: loginResp.id,
    file_uri: `/test/uploads/testfile_v1.txt`,
    file_size: 12345,
    diff_comment: "Initial version upload",
  } satisfies IShoppingMallAiAttachmentVersion.ICreate;
  const version = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.createVersion(connection, {
    attachmentId: attachment.id,
    body: versionBody,
  });
  typia.assert(version);
  TestValidator.equals("version's modified_by_id is admin")(version.modified_by_id)(loginResp.id);
  TestValidator.equals("version is not deleted")(version.deleted)(false);
  TestValidator.equals("attachment_id matches")(version.attachment_id)(attachment.id);
  TestValidator.equals("version_number is 1")(version.version_number)(1);

  // 5. Fetch attachment version full metadata as admin
  const meta = await api.functional.shoppingMallAi.administrator.attachments.attachmentVersions.atVersion(connection, {
    attachmentId: attachment.id,
    attachmentVersionId: version.id,
  });
  typia.assert(meta);

  // 6. Validate all fields match version, and audit/compliance values are correct
  TestValidator.equals("fetched version id matches")(meta.id)(version.id);
  TestValidator.equals("modified_by_id matches")(meta.modified_by_id)(loginResp.id);
  TestValidator.equals("attachment_id matches")(meta.attachment_id)(attachment.id);
  TestValidator.equals("deleted flag matches")(meta.deleted)(false);
  TestValidator.equals("file_uri matches")(meta.file_uri)(version.file_uri);
  TestValidator.equals("file_size matches")(meta.file_size)(version.file_size);
  TestValidator.equals("version_number is 1")(meta.version_number)(1);
  TestValidator.equals("diff_comment matches")(meta.diff_comment)(versionBody.diff_comment);
  TestValidator.predicate("created_at is ISO string")(/^\d{4}-\d{2}-\d{2}T/.test(meta.created_at));
}

