 * 1. Register a new administrator, acquiring credentials and JWT headers.
 * 2. Login as the new administrator and verify token/headers are issued.
 * 3. Create a new attachment record to act as the parent entity for version creation.
 * 4. Create an attachment version for this attachment with compliant metadata.
 * 5. Update the version's metadata as administrator (e.g., set new diff_comment, change deleted flag).
 * 6. Verify all updatable properties (diff_comment, deleted) were updated successfully and that immutable fields remain unchanged, ensuring proper audit trail behavior.
 */
export async function test_api_update_attachment_version_metadata_success(connection: api.IConnection) {
