  TestValidator.equals("version parent matches")(attachmentVersion.attachment_id)(attachmentResult.id);
  TestValidator.equals("version modifier matches")(attachmentVersion.modified_by_id)(registerResult.id);

  // 5. Update the version metadata (set diff_comment and deleted to true)
