  TestValidator.equals("updated modifier unchanged")(updatedVersion.modified_by_id)(attachmentVersion.modified_by_id);
  TestValidator.equals("version number unchanged")(updatedVersion.version_number)(attachmentVersion.version_number);
  TestValidator.equals("file_uri unchanged")(updatedVersion.file_uri)(attachmentVersion.file_uri);
  TestValidator.equals("file_size unchanged")(updatedVersion.file_size)(attachmentVersion.file_size);
  TestValidator.equals("created_at unchanged")(updatedVersion.created_at)(attachmentVersion.created_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
