      password_hash: passwordHash,
      display_name: displayName,
      status: "active",
      role
    }
  });
  typia.assert(admin);

  // 2. Login as administrator
  const loggedInAdmin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: passwordHash
    }
  });
