 * This test ensures that attachments and their business links are protected by domain-level access controls,
 * preventing unauthorized admin users from retrieving confidential linkage details (e.g., evidence, legal docs,
 * restricted orders). Steps:
 *   1. Register administrator1 (active status/role), who will create restricted domain resources.
 *   2. Login as administrator1 – obtain authenticated session (JWT header set).
 *   3. Register an attachment as administrator1 and record its UUID.
 *   4. Create a business link to a restricted target domain/entity as administrator1 and record its UUID.
 *   5. Register administrator2 (active status/role), representing a separate admin (no domain ownership).
 *   6. Login as administrator2 – activating a new session with separate authorization.
 *   7. Attempt as administrator2 to fetch the business link using both UUIDs (should be rejected, access denied).
 *   8. Verify error occurs – validate that unauthorized access is prevented.
 */
export async function test_api_attachment_business_link_get_unauthorized_access(connection: api.IConnection) {
  // 1. Register administrator 1
  const admin1Email = typia.random<string & tags.Format<"email">>();
