      file_size: 1024,
      business_domain: "evidence",
      retention_policy_code: "legal-hold",
      legal_hold: true,
      access_acl: JSON.stringify({ allow: [admin1.id], deny: [] })
    } satisfies IShoppingMallAiAttachment.ICreate
  });
  typia.assert(attachment);

  // 4. Create a private/restricted business link to the attachment (admin1 is owner)
  const targetId = typia.random<string & tags.Format<"uuid">>();
  const businessLink: IAttachment.AttachmentBusinessLink = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.create(connection, {
