import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachment";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate the system's enforcement of referential integrity when attempting to link an attachment to a non-existent business target. This test ensures the API returns an error, does not create the association, and logs the event for audit/compliance in failure scenarios.
 *
 * 1. Register a new administrator account with unique credentials (email, password_hash, display_name, status, role).
 * 2. Authenticate as the administrator to receive authorization headers for subsequent requests.
 * 3. Create an attachment as the administrator, storing received attachment id and current admin id for future linking attempts.
 * 4. Attempt to create a business link between the attachment and a deliberately invalid/non-existent business target (using a random valid uuid as target_id and a plausible but unused domain string). Use the actual administrator's id as linked_by_id.
 * 5. Confirm the API enforces referential integrity by rejecting the request (error thrown). TestValidator.error() should be used to ensure an exception is thrown, and no business link is created on invalid reference.
 */
export async function test_api_attachment_business_link_create_invalid_target(
  connection: api.IConnection,
) {
  // 1. Register a new administrator
  const uniqueAdminEmail = typia.random<string & tags.Format<"email">>();
  const passwordHash = "$2b$12$" + RandomGenerator.alphaNumeric(22); // plausible bcrypt format
  const administrator = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: uniqueAdminEmail,
      password_hash: passwordHash,
      display_name: RandomGenerator.name(),
      status: "active",
      role: "superadmin",
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(administrator);

  // 2. Authenticate as the just-registered administrator
  const adminAuth = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: uniqueAdminEmail,
      password_hash: passwordHash,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(adminAuth);

  // Authorization header updated in connection.headers automatically

  // 3. Create an attachment as administrator
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      uploaded_by_id: administrator.id,
      filename: RandomGenerator.alphaNumeric(12) + ".jpg",
      mime_type: "image/jpeg",
      file_uri: "https://cdn.example.com/files/" + typia.random<string & tags.Format<"uuid">>(),
      file_size: 12345,
      business_domain: "evidence",
      retention_policy_code: "standard",
      legal_hold: false,
      access_acl: '{"role": ["superadmin"]}',
    } satisfies IShoppingMallAiAttachment.ICreate,
  });
  typia.assert(attachment);

  // 4. Attempt to create business link with invalid target_id
  // Generate a random UUID that does not correspond to any real business entity
  const invalidTargetId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("attempting to link to a non-existent business target should fail")(
    () =>
      api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.create(connection, {
        attachmentId: attachment.id,
        body: {
          target_domain: "nonexistent_entity",
          target_id: invalidTargetId,
          linked_by_id: administrator.id,
        } satisfies IAttachment.AttachmentBusinessLink.ICreate,
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallAiAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiAttachment";
import type { IAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachment";
import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Validate successful update of an attachment-business link (domain/target/actor).
 *
 * This test verifies that an administrator can update the properties of an attachment-business link—specifically, domain, target, and/or actor—and that such metadata changes are reflected correctly. All business integrity, referential, and permission rules are respected throughout this workflow.
 *
 * Steps:
 * 1. Register a new administrator and log in. Authentication is required to receive the Authorization header for subsequent operations.
 * 2. Register a new attachment via the administrator API (metadata registration only). Capture the returned attachment's id and uploaded_by_id for provenance.
 * 3. With the attachment, create an initial business link associating it to a business domain and target (e.g., product, order, evidence) and record the admin as the actor (linked_by_id).
 * 4. Update the attachment-business link by supplying new values for target_domain, target_id, and linked_by_id via the update API. Use new, randomly generated but valid values to simulate a realistic update scenario (e.g., domain correction, target swap, actor reassignment).
 * 5. Assert the response reflects all updates: updated domain, target, and/or actor are shown in the returned object. Check that audit/control fields like id, attachment_id, and created_at remain unchanged, but updated properties match the request (if supplied).
 */
export async function test_api_attachment_business_link_update_success(
  connection: api.IConnection,
) {
  // 1. Register administrator
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphabets(16);

  const adminRegistration = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
      display_name: RandomGenerator.name(),
      status: "active",
      role: "superadmin",
    },
  });
  typia.assert(adminRegistration);
  connection.headers = { ...connection.headers, ...adminRegistration.setHeaders };

  // 2. Login as administrator (explicit, allows token refresh/validation)
  const adminLogin = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: adminEmail,
      password_hash: adminPassword,
    },
  });
  typia.assert(adminLogin);
  connection.headers = { ...connection.headers, ...adminLogin.setHeaders };

  // 3. Create an attachment
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      uploaded_by_id: adminLogin.id,
      filename: `${RandomGenerator.alphabets(8)}.jpg`,
      mime_type: "image/jpeg",
      file_uri: `https://cdn.example.com/${RandomGenerator.alphaNumeric(10)}.jpg`,
      file_size: 1024,
      business_domain: "product_image",
      retention_policy_code: "standard",
      legal_hold: false,
      access_acl: "{\"admins\":[\"*\"]}",
    },
  });
  typia.assert(attachment);

  // 4. Create an attachment-business link
  const businessLink = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.create(connection, {
    attachmentId: attachment.id,
    body: {
      target_domain: "product",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      linked_by_id: adminLogin.id,
    },
  });
  typia.assert(businessLink);

  // 5. Update the business link
  const updatedData = {
    target_domain: "evidence",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    linked_by_id: adminLogin.id,
  };
  const updatedLink = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.update(connection, {
    attachmentId: attachment.id,
    attachmentBusinessLinkId: businessLink.id,
    body: updatedData,
  });
  typia.assert(updatedLink);

  // 6. Assert updated properties
  TestValidator.equals("attachment id matches")(updatedLink.attachment_id)(attachment.id);
  TestValidator.equals("business link id matches")(updatedLink.id)(businessLink.id);
  TestValidator.equals("target domain updated")(updatedLink.target_domain)(updatedData.target_domain);
  TestValidator.equals("target id updated")(updatedLink.target_id)(updatedData.target_id);
  TestValidator.equals("linked_by_id updated")(updatedLink.linked_by_id)(updatedData.linked_by_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
