import type { IAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdministrator";

/**
 * Test unauthorized update attempt of an attachment-business link by a non-owning administrator
 *
 * This test validates that the system properly rejects updates to an attachment-business link record by an administrator who is not the creator/owner, ensuring permissions and audit compliance.
 *
 * Test Steps:
 * 1. Register admin1 and login, capturing the authentication header.
 * 2. As admin1, create an attachment using random but valid attachment data.
 * 3. As admin1, create an attachment-business link for this attachment.
 * 4. Register and login a second administrator, admin2, capturing their authentication header.
 * 5. As admin2 (who does not own the link), attempt to update the attachment-business link with new random data. 
 * 6. Verify the API rejects the update attempt with a permission/authorization error, and that an audit log is created per scenario requirements (audit log cannot be directly confirmed here, but permission error is testable).
 *
 * This test ensures that access controls are enforced for update operations on attachment-business links and that only the owning or appropriately privileged administrator can perform such updates. It also checks correct propagation of authentication tokens between users. Edge cases: test that admin2 cannot change any updatable field, and that the rejection is consistent regardless of input data.
 */
export async function test_api_attachment_business_link_update_unauthorized(connection: api.IConnection) {
  // 1. Register admin1
  const admin1Email = typia.random<string & tags.Format<"email">>();
  const admin1Password = "hashed_pw_1";
  const admin1DisplayName = RandomGenerator.name();
  const admin1Reg = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: admin1Email,
      password_hash: admin1Password,
      display_name: admin1DisplayName,
      status: "active",
      role: "manager",
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(admin1Reg);
  connection.headers = { ...(connection.headers ?? {}), ...admin1Reg.setHeaders };

  // 2. Login as admin1 (ensure we have latest token)
  const login1 = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: admin1Email,
      password_hash: admin1Password,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(login1);
  connection.headers = { ...(connection.headers ?? {}), ...login1.setHeaders };

  // 3. Create attachment as admin1
  const attachment = await api.functional.shoppingMallAi.administrator.attachments.create(connection, {
    body: {
      uploaded_by_id: admin1Reg.id,
      filename: RandomGenerator.alphaNumeric(10),
      mime_type: "application/pdf",
      file_uri: "https://example.com/file.pdf",
      file_size: 1024,
      business_domain: "evidence",
      retention_policy_code: "standard",
      legal_hold: false,
      access_acl: `{"admins":["${admin1Reg.id}"]}`,
    } satisfies IShoppingMallAiAttachment.ICreate,
  });
  typia.assert(attachment);

  // 4. Create attachment-business link as admin1
  const businessLink = await api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.create(connection, {
    attachmentId: attachment.id,
    body: {
      target_domain: "product",
      target_id: typia.random<string & tags.Format<"uuid">>(),
      linked_by_id: admin1Reg.id,
    } satisfies IAttachment.AttachmentBusinessLink.ICreate,
  });
  typia.assert(businessLink);

  // 5. Register and login as admin2
  const admin2Email = typia.random<string & tags.Format<"email">>();
  const admin2Password = "hashed_pw_2";
  const admin2DisplayName = RandomGenerator.name();
  const admin2Reg = await api.functional.auth.administrator.register.signUp(connection, {
    body: {
      email: admin2Email,
      password_hash: admin2Password,
      display_name: admin2DisplayName,
      status: "active",
      role: "manager",
    } satisfies IAdministrator.ICreate,
  });
  typia.assert(admin2Reg);
  connection.headers = { ...(connection.headers ?? {}), ...admin2Reg.setHeaders };

  const login2 = await api.functional.auth.administrator.login.signIn(connection, {
    body: {
      email: admin2Email,
      password_hash: admin2Password,
    } satisfies IAdministrator.ILogin,
  });
  typia.assert(login2);
  connection.headers = { ...(connection.headers ?? {}), ...login2.setHeaders };

  // 6. Attempt to update business link as admin2 (should fail)
  await TestValidator.error("should block unauthorized business link update")(
    async () =>
      api.functional.shoppingMallAi.administrator.attachments.attachmentBusinessLinks.update(connection, {
        attachmentId: attachment.id,
        attachmentBusinessLinkId: businessLink.id,
        body: {
          target_domain: "order",
          target_id: typia.random<string & tags.Format<"uuid">>(),
          linked_by_id: admin2Reg.id,
        } satisfies IAttachment.AttachmentBusinessLink.IUpdate,
      })
